import type { Message } from './extraction';
import type { Candidate, Review } from './review';
import { candidateKey, conflictsForReview } from './reanalysis';

export const fieldNames = ['interest', 'location', 'horizon', 'buyers', 'income', 'savings', 'debts'] as const;
export type Field = typeof fieldNames[number];
export type EffectiveValue = { value: string; provenance: 'candidate' | 'confirmed' | 'corrected' | 'adopted'; source: Message | null; quote: string; note: string; metadata: Pick<Candidate, 'precision' | 'subject' | 'incomeBasis' | 'debtIncluded' | 'uncertainty'> | null };
export type EffectiveField = { humanReviews: Review[]; status: 'missing' | 'discarded' | 'conflict' | 'available'; selected: EffectiveValue | null; evidence: { candidate: Candidate; source: Message | null }[] };
export type EffectiveSheet = Record<Field, EffectiveField>;
type Input = { candidates: Candidate[]; messages: Message[]; reviews: Record<string, Review>; baselines: Record<string, string[]>; resolutions: Record<string, 'keep' | 'adopt'> };

export function deriveEffective(input: Input): EffectiveSheet {
  const { candidates, messages, reviews, baselines, resolutions } = input;
  const source = (c: Candidate) => messages.find(m => m.id === c.messageId) ?? null;
  const key = (c: Candidate) => { const m = source(c); return m ? candidateKey(c, m) : ''; };
  const result = {} as EffectiveSheet;
  for (const field of fieldNames) {
    const items = candidates.filter(c => c.field === field);
    const evidence = items.map(candidate => ({ candidate, source: source(candidate) }));
    const fieldReviews = Object.entries(reviews).filter(([, r]) => r.candidate.field === field);
    const humanReviews = fieldReviews.map(([, r]) => r);
    const keys = items.map(key);
    const ambiguous = keys.some((k, i) => !k || keys.indexOf(k) !== i);
    const relevant = fieldReviews.filter(([k]) => keys.includes(k));
    if (ambiguous || fieldReviews.length !== relevant.length || relevant.length > 1) { result[field] = { status: 'conflict', selected: null, evidence, humanReviews }; continue; }
    const [reviewKey, review] = relevant[0] ?? [];
    if (review?.status === 'discarded') {
      result[field] = { status: items.length > 1 ? 'conflict' : 'discarded', selected: null, evidence, humanReviews }; continue;
    }
    if (review && ((review.status === 'confirmed' && items.length > 1) || (review.status === 'corrected' && (baselines[reviewKey]?.length ?? 0) > 1))) { result[field] = { status: 'conflict', selected: null, evidence, humanReviews }; continue; }
    let chosen: Candidate | undefined;
    let provenance: EffectiveValue['provenance'] = 'candidate';
    if (review) {
      const changed = conflictsForReview(review, items).filter(c => !baselines[reviewKey]?.includes(JSON.stringify([key(c), c.value])));
      const decisions = changed.map(c => resolutions[JSON.stringify([reviewKey, key(c), c.value])]);
      const adopted = changed.filter((_, i) => decisions[i] === 'adopt');
      if (decisions.some(d => !d) || adopted.length > 1) { result[field] = { status: 'conflict', selected: null, evidence, humanReviews }; continue; }
      if (adopted.length === 1) { chosen = adopted[0]; provenance = 'adopted'; }
      else {
        chosen = items.find(c => key(c) === reviewKey);
        provenance = review.status;
      }
    } else {
      if (!items.length) { result[field] = { status: 'missing', selected: null, evidence, humanReviews }; continue; }
      if (items.length > 1) { result[field] = { status: 'conflict', selected: null, evidence, humanReviews }; continue; }
      chosen = items[0];
    }
    if (!chosen) { result[field] = { status: 'conflict', selected: null, evidence, humanReviews }; continue; }
    const corrected = provenance === 'corrected';
    result[field] = { status: 'available', evidence, humanReviews, selected: { value: corrected ? review.value : chosen.value, provenance, source: corrected ? review.source : source(chosen), quote: corrected ? review.candidate.quote : chosen.quote, note: corrected ? review.note : '', metadata: corrected ? null : { precision: chosen.precision, subject: chosen.subject, incomeBasis: chosen.incomeBasis, debtIncluded: chosen.debtIncluded, uncertainty: chosen.uncertainty } } };
  }
  return result;
}
import { fieldNames, type EffectiveSheet } from './effective';
import { intakeRules, type IntakeRules } from './rules';
export type IssueStatus = 'pending' | 'resolved' | 'dismissed';
export type ReviewedIssue = { category: string; status: IssueStatus; description?: string };
export type Stage = 'Nuevo' | 'En cualificación' | 'Cualificado';
export function canUseQuestion(issues: ReviewedIssue[]): boolean {
  return !issues.some(i => i.category === 'sensitive' && i.status === 'pending');
}
export function suggestedStage({ analyzed, alias, sheet, pendingIssues, rules = intakeRules }: { analyzed: boolean; alias: string; sheet: EffectiveSheet; pendingIssues: ReviewedIssue[]; rules?: IntakeRules }): Stage {
  if (!analyzed) return 'Nuevo';
  if (!alias.trim() || fieldNames.some(f => sheet[f].status === 'conflict') || rules.requiredFields.some(f => sheet[f].status !== 'available') || pendingIssues.some(i => i.status === 'pending')) return 'En cualificación';
  const interest = sheet.interest.selected?.value ?? '';
  if (rules.requiredFields.includes('interest') && (!/smart\s*housing/i.test(interest) || !/inter[eé]s|interesad|quier|explor/i.test(interest) || /\b(?:no|sin|desinter[eé]s)\b/i.test(interest))) return 'En cualificación';
  const income = sheet.income.selected?.metadata;
  if (rules.requiredFields.includes('income') && (!income || income.incomeBasis === 'unknown' || income.subject === 'unknown')) return 'En cualificación';
  if (sheet.debts.status === 'conflict' || sheet.debts.selected?.metadata?.debtIncluded === 'unknown') return 'En cualificación';
  return 'Cualificado';
}
import type { extract } from './extraction';
import type { identifyIssues, Issue } from './issues';
import { intakeRules, type IntakeRules } from './rules';

type Extraction = Awaited<ReturnType<typeof extract>>;
type Issues = ReturnType<typeof identifyIssues>;
type Field = NonNullable<Issue['field']>;

const missingQuestions: Record<Exclude<Field, 'debts'>, string> = {
  interest: '¿Os interesa explorar SmartHousing?',
  location: '¿En qué zona buscáis vivienda?',
  horizon: '¿En qué plazo queréis comprar?',
  buyers: '¿Quiénes compraríais la vivienda?',
  income: '¿Cuáles son vuestros ingresos mensuales?',
  savings: '¿Cuánto tenéis ahorrado?',
};
const clarificationQuestions: Record<Field, string> = {
  interest: '¿Podéis aclarar vuestro interés en SmartHousing?',
  location: '¿Podéis aclarar la zona en la que buscáis vivienda?',
  horizon: '¿Podéis aclarar el plazo en el que queréis comprar?',
  buyers: '¿Podéis aclarar quiénes compraríais la vivienda?',
  income: '¿Podéis aclarar los ingresos que habéis indicado?',
  savings: '¿Podéis aclarar los ahorros que habéis indicado?',
  debts: '¿Podéis aclarar la cuota que habéis indicado?',
};

type Result =
  | { kind: 'error'; error: Extract<Extraction, { ok: false }>['error'] }
  | { kind: 'human_review'; label: 'Revisión del asesor'; reason: string; issueId: string; field?: Field }
  | { kind: 'question'; question: string; reason: string; field: Field; issueId: string }
  | { kind: 'none'; label: 'Sin preguntas pendientes prioritarias' };

/** Selecciona una intervención propuesta; no envía ni modifica datos. */
export function nextQuestion(extraction: Extraction, result: Issues, rules: IntakeRules = intakeRules): Result {
  if (!extraction.ok) return { kind: 'error', error: extraction.error };
  if (!result.ok) return { kind: 'error', error: result.error };

  const sensitive = result.issues.find(issue => issue.category === 'sensitive');
  if (sensitive) return { kind: 'human_review', label: 'Revisión del asesor', reason: sensitive.description, issueId: sensitive.id, ...(sensitive.field ? { field: sensitive.field } : {}) };

  const ambiguities = result.issues.filter(issue => issue.category === 'ambiguous');
  // D emite esta descripción concreta para la base; tiene prioridad sobre otras dudas económicas.
  const basis = rules.prioritizeIncomeBasis ? ambiguities.find(issue => issue.field === 'income' && issue.description === 'No se conoce si los ingresos son netos o brutos.') : undefined;
  const ambiguity = basis ?? rules.ambiguityOrder.map(field => ambiguities.find(issue => issue.field === field)).find(Boolean) ?? ambiguities[0];
  if (ambiguity) {
    if (!ambiguity.field) return { kind: 'human_review', label: 'Revisión del asesor', reason: ambiguity.description, issueId: ambiguity.id };
    let question = clarificationQuestions[ambiguity.field];
    if (ambiguity === basis) question = '¿Los ingresos mensuales que habéis indicado son netos o brutos?';
    if (ambiguity.field === 'debts' && ambiguity.description === 'No se conoce si la cuota está descontada de los ingresos.') question = '¿La cuota que habéis indicado ya está descontada de vuestros ingresos?';
    return { kind: 'question', question, reason: ambiguity.description, field: ambiguity.field, issueId: ambiguity.id };
  }

  for (const field of rules.requiredFields) {
    const issue = result.issues.find(item => item.category === 'missing' && item.field === field);
    if (issue) return { kind: 'question', question: missingQuestions[field], reason: issue.description, field, issueId: issue.id };
  }
  return { kind: 'none', label: 'Sin preguntas pendientes prioritarias' };
}

