function alert(){return state.sensitive?`<section class="alert"><div><strong>Revisión del asesor necesaria</strong><p>El cliente pide modificar ingresos para que parezcan mayores. No se debe presentar esa cifra como verificada.</p></div><button data-action="resolve-sensitive">Marcar revisada</button></section>`:''}
function next(){return state.sensitive?`<div class="next"><span class="label">SIGUIENTE PASO</span><h2>Revisa la solicitud sensible</h2><p>Antes de formular una pregunta, decide cómo tratar la petición del cliente.</p><button data-action="focus-alert">Ir a la revisión <span>↗</span></button></div>`:`<div class="next"><span class="label">PREGUNTA RECOMENDADA</span><h2>¿Los ingresos mensuales que habéis indicado son netos o brutos?</h2><p>La base de los 3.800 € no está clara. Pregunta editable y para uso manual.</p><button data-action="copy-question">Copiar pregunta</button><span id="copy-status" role="status"></span></div>`}
function table(){return `<div class="fields">${fields.map(([label,value,id])=>`<div class="field"><span>${label}</span><strong>${esc(label==='Ingresos mensuales'&&state.reviewed?'3.800 € · revisado, base sin aclarar':value)}</strong><button data-action="source" data-id="${id}" aria-label="Ver fuente de ${label}">Fuente ${id}</button></div>`).join('')}</div>`}
function issues(){return `<section class="issues"><div class="section-head"><div><span class="label">ATENCIÓN</span><h2>Incidencias</h2></div><span>${(state.conflict?1:0)+(state.sensitive?1:0)} pendientes</span></div>${alert()}${state.conflict?`<div class="issue"><div><strong>Ingresos · conflicto de revisión</strong><p>Una revisión anterior no coincide con la propuesta actual. La ficha CRM está bloqueada.</p></div><button data-action="resolve-conflict">Resolver ejemplo</button></div>`:`<div class="issue"><div><strong>Conflicto de ejemplo resuelto</strong><p>La resolución es local al prototipo y no modifica el motor real.</p></div><button data-action="reset-conflict">Restaurar conflicto</button></div>`}</section>`}
function exportBox(){let blocked=state.conflict||state.stale;return `<section class="export"><div><span class="label">SALIDA MANUAL</span><h2>Ficha para CRM</h2><p>${state.stale?'El análisis está desactualizado. Vuelve a cargar el resultado de ejemplo.':blocked?'Bloqueada por un conflicto pendiente. Puedes consultar la vista previa.':'Disponible para copia manual. No se sincroniza con ningún CRM.'}</p></div><button data-action="export">${blocked?'Ver vista previa':'Preparar ficha'}</button></section>`}
function source(){return state.source?`<div class="scrim"><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="source-title"><button class="close" data-action="close">Cerrar ×</button><span class="label">FUENTE ${state.source.toUpperCase()}</span><h2 id="source-title">Fragmento de conversación</h2><blockquote>${esc(({m1:'Buscamos vivienda en Valencia y nos interesa SmartHousing.',m2:'Compramos mi pareja y yo, pensamos mudarnos en unos seis meses.',m3:'Entre los dos ingresamos 3.800 € al mes, pero no sé si te he dicho la cifra neta o bruta.',m4:'Tenemos unos 25.000 € ahorrados y una cuota de coche de 240 €.'})[state.source])}</blockquote><p>Declaración del cliente · dato no verificado documentalmente.</p><button class="primary" data-action="review">Marcar dato revisado</button><button data-action="close">Volver al expediente</button></aside></div>`:''}
function exportDialog(){let blocked=state.conflict||state.stale;return state.export?`<div class="scrim"><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="export-title"><button class="close" data-action="close">Cerrar ×</button><span class="label">${blocked?'VISTA PREVIA NO EXPORTABLE':'FICHA MANUAL'}</span><h2 id="export-title">Ficha para CRM</h2><p>${blocked?'Hay un bloqueo pendiente; esta vista no es exportable.':'Lista para copiar manualmente. No se ha actualizado ningún CRM.'}</p><pre>${esc('Laura · En cualificación\nDatos autodeclarados; no verificados.\n\n'+fields.map(([a,b])=>`${a}: ${b}`).join('\n')+'\n\nIncidencias: revisión de ingresos pendiente.')}</pre>${blocked?'':`<button class="primary" data-action="copy-export">Copiar ficha de ejemplo</button><span id="copy-status" role="status"></span>`}</aside></div>`:''}
function continuation(){return `<section class="continuation"><h2>Añadir información</h2><p>La nueva intervención deja el resultado anterior desactualizado.</p><textarea id="new-message" rows="3" placeholder="Escribe una intervención ficticia"></textarea><button data-action="add">Añadir intervención</button>${state.stale?'<p class="warn">Resultado desactualizado · el prototipo no reanaliza texto. <button data-action="reload">Cargar de nuevo el ejemplo</button></p>':''}</section>`}
function brief(){return `<main class="brief"><div class="brief-heading"><div><span class="label">EXPEDIENTE FICTICIO / LAURA</span><h1>Una compra en<br><em>Valencia.</em></h1><p>En cualificación <span>·</span> Información declarada por el cliente</p></div><button data-action="entry">Editar conversación</button></div><div class="brief-grid"><div>${next()}<section class="profile"><div class="section-head"><div><span class="label">PERFIL COMERCIAL</span><h2>Lo que sabemos</h2></div><span>7 atributos</span></div>${table()}</section></div><aside>${issues()}${exportBox()}${continuation()}</aside></div></main>`}
function workbench(){return `<main class="workbench"><div class="work-head"><div><span class="label">EXPEDIENTE / LAURA</span><h1>Revisión comercial</h1></div><div>En cualificación <button data-action="entry">Conversación</button></div></div><div class="work-grid"><aside class="work-left"><h2>Conversación</h2><p class="muted">5 intervenciones · ficticias</p><div class="transcript">${conversation.split('\n').map((x,i)=>`<div><span>m${i+1} · Cliente</span><p>${esc(x.replace('Cliente: ',''))}</p></div>`).join('')}</div>${continuation()}</aside><section class="work-center"><div class="section-head"><div><span class="label">FICHA EFECTIVA</span><h2>Datos del cliente</h2></div><span>Autodeclarados</span></div>${table()}${exportBox()}</section><aside class="work-right">${next()}${issues()}</aside></div></main>`}
function queue(){return `<main class="queue"><div class="queue-head"><div><span class="label">LAURA / EN CUALIFICACIÓN</span><h1>Tu siguiente paso</h1><p>Resuelve lo que requiere tu criterio y prepara la ficha.</p></div><button data-action="entry">Ver conversación</button></div><div class="queue-grid"><section class="queue-main">${next()}${issues()}${exportBox()}${continuation()}</section><aside class="queue-profile"><div class="section-head"><div><span class="label">CONTEXTO</span><h2>Ficha de Laura</h2></div></div><p>Información parcial, declarada por el cliente.</p>${table()}</aside></div></main>`}
function render(){document.body.className='concept-'+concept;document.getElementById('app').innerHTML=nav()+(state.analyzed?(concept==='a'?brief():concept==='b'?workbench():queue()):entry())+source()+exportDialog();}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='analyze'||a==='reload'){state.analyzed=true;state.stale=false}else if(a==='entry')state.analyzed=false;else if(a==='source')state.source=b.dataset.id;else if(a==='close'){state.source=false;state.export=false}else if(a==='review'){state.reviewed=true;state.source=false}else if(a==='resolve-sensitive')state.sensitive=false;else if(a==='resolve-conflict')state.conflict=false;else if(a==='reset-conflict')state.conflict=true;else if(a==='focus-alert'){document.querySelector('.alert')?.scrollIntoView({behavior:'smooth',block:'center'});return}else if(a==='export')state.export=true;else if(a==='add'){if(!document.getElementById('new-message')?.value.trim())return;state.stale=true}else if(a.startsWith('copy-')){let txt=a==='copy-question'?'¿Los ingresos mensuales que habéis indicado son netos o brutos?':document.querySelector('pre')?.innerText;try{await navigator.clipboard.writeText(txt);document.getElementById('copy-status').textContent=' Copiado';}catch{document.getElementById('copy-status').textContent=' No se pudo copiar; selecciona el texto manualmente.'}return}render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(state.source||state.export)){state.source=false;state.export=false;render()}});render();
EOF

